// Alice encrypts message for Bob
ciphertext = encrypt(bob_public_key, plaintext)
send(ciphertext)

// Bob decrypts
plaintext = decrypt(bob_private_key, ciphertext)

// Bob signs a message
signature = sign(bob_private_key, message)
// Anyone can verify
isValid = verify(bob_public_key, message, signature)
